lessons.example:
/* Try with <main><p class="note">Study note</p></main>. */
main { color: #202639; }
p { line-height: 1.55; }
.note { color: #194a7a; }
main .note { color: #0d3c66; }

/* Try with <article class="card">A long study note</article>. */
.card {
  box-sizing: border-box;
  inline-size: 100%;
  max-inline-size: 28rem;
  margin-inline: auto;
  padding: 1rem;
  border: 1px solid #778399;
  overflow-wrap: anywhere;
}

/* Try with a .toolbar containing three buttons, one with class .push. */
.toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.5rem;
}

.toolbar .push { margin-inline-start: auto; }

/* Try with a .topics container and several article children. */
.topics {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 14rem), 1fr));
  gap: 1rem;
}

.topics article { min-inline-size: 0; padding: 0.75rem; }

:root { --paper: #fff; --ink: #17223a; }
body { background: var(--paper); color: var(--ink); margin: 1rem; }

@media (prefers-color-scheme: dark) {
  :root { --paper: #151a25; --ink: #e6ebf5; }
}

@media (min-width: 48rem) {
  body { margin: 2rem; }
}

/* Try with <button class="action" type="button">Open lesson</button>. */
.action { padding: 0.55rem 0.8rem; }
.action:hover { text-decoration: underline; }
.action:focus-visible { outline: 2px solid #3778bc; outline-offset: 3px; }

@media (prefers-reduced-motion: no-preference) {
  .action { transition: background-color 120ms ease; }
}
